import {STORE_KEY,TARGETS,initialState,transition,restoreState,agentInput,pinsFor,targetFor,normalizeRegion} from './model.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={arrow:'M7 17 17 7M7 7h10v10',back:'m15 18-6-6 6-6',close:'m6 6 12 12M6 18 18 6',plus:'M12 5v14M5 12h14',minus:'M5 12h14',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0ZM12 10h.01',select:'M4 9V4h5M15 4h5v5M20 15v5h-5M9 20H4v-5',send:'m21 3-7 18-4-7-7-4 18-7ZM10 14 21 3',check:'m5 12 4 4L19 6',compare:'M12 3v18M3 5h6v14H3zM15 5h6v14h-6z',image:'M3 3h18v18H3zM3 17l6-6 4 4 3-3 5 5M15 7h.01',message:'M21 15a3 3 0 0 1-3 3H8l-5 3V6a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3z',robot:'M12 3v3M9 3h6M5 8h14v12H5zM2 11v6M22 11v6M9 12h.01M15 12h.01M9 16h6',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',sun:'M12 3v2M12 19v2M3 12h2M19 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M21 12.8A9 9 0 1 1 11.2 3 7 7 0 0 0 21 12.8',edit:'m14 5 5 5M3 21l5-1L21 7l-5-5L3 15z',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',refresh:'M20 7V3l-4 4M4 17v4l4-4M20 7a9 9 0 0 0-16 3M4 17a9 9 0 0 0 16-3',chevron:'m9 5 7 7-7 7',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
const button=(label,action,kind='',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
let state;try{state=restoreState(sessionStorage.getItem(STORE_KEY));}catch{state=initialState();}
let selected=state.threads.at(-1)?.id||null,versionId=state.threads.at(-1)?.revisionId||'original',draft=null,compare=false,zoom=1,editing=null,reopening=false,undoState=null;
let page=location.hash==='#issue'?'issue':'review';
const timers=new Map();
function current(){return state.threads.find(t=>t.id===selected);}
function version(id=versionId){return state.versions.find(v=>v.id===id)||state.versions[0];}
function announce(text){$('#announcement').textContent=text;}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);announce(text);}
function save(){try{sessionStorage.setItem(STORE_KEY,JSON.stringify(state));}catch{toast('This browser could not save the demo. Keep this tab open.');}}
function dispatch(event){const previous=state;state=transition(state,event);if(previous===state)return false;save();schedule();return true;}
function schedule(){for(const t of state.threads){if(!['sent','working'].includes(t.phase)||timers.has(t.id))continue;timers.set(t.id,setTimeout(()=>{timers.delete(t.id);const active=state.threads.find(x=>x.id===t.id);if(!active)return;const action=active.phase==='sent'?'receive':active.phase==='working'?'revise':null;if(!action)return;dispatch({type:action,id:t.id});if(action==='revise'&&selected===t.id){versionId=state.threads.find(x=>x.id===t.id).revisionId;compare=false;}render(true);announce(action==='receive'?'Your agent has a question about this feedback.':'A sample revision is ready to compare.');},t.phase==='sent'?900:1800));}}
function art(id=versionId,uid='main'){
 const c=version(id).changes,h=Math.min(3,c.heading||0)*7,s=Math.min(3,c.social||0)*6,f=Math.min(2,c.fields||0)*5,b=Math.min(2,c.button||0)*14,w=Math.min(3,c.welcome||0)*7;
 return `<svg class="screenshot" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 600" role="img" aria-label="Illustrative signup attachment. ${Object.keys(c).length?'A sample spacing revision.':'Original layout with tight space above the create account button.'}">
 <defs><linearGradient id="g-${uid}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#1b3d8b"/><stop offset="1" stop-color="#142b61"/></linearGradient><clipPath id="clip-${uid}"><rect width="960" height="600" rx="6"/></clipPath><clipPath id="left-${uid}"><rect y="35" width="454" height="565"/></clipPath></defs>
 <g clip-path="url(#clip-${uid})"><rect width="960" height="600" fill="#fff"/><rect width="960" height="35" fill="#f4f6fa"/><circle cx="18" cy="17" r="4" fill="#ff9c95"/><circle cx="32" cy="17" r="4" fill="#f5ce76"/><circle cx="46" cy="17" r="4" fill="#82c9a2"/><rect x="327" y="8" width="306" height="18" rx="5" fill="#e8ecf2"/><text x="480" y="21" font-family="Arial,sans-serif" font-size="9" text-anchor="middle" fill="#7b8598">app.zedu.chat / create-account</text>
 <g clip-path="url(#left-${uid})"><rect y="35" width="454" height="565" fill="url(#g-${uid})"/><circle cx="61" cy="510" r="225" fill="none" stroke="#5774b0" stroke-opacity=".3"/><circle cx="61" cy="510" r="171" fill="none" stroke="#5774b0" stroke-opacity=".25"/><circle cx="425" cy="106" r="133" fill="#6385cd" opacity=".1"/>
 <path d="m50 72 13 0-10 11h11v5H47v-5l10-7h-7z" fill="#a8c5ff"/><text x="74" y="87" font-family="Arial,sans-serif" font-size="23" font-weight="700" fill="white">zedu</text>
 <rect x="49" y="180" width="123" height="26" rx="13" fill="#385997"/><circle cx="62" cy="193" r="3" fill="#9eceff"/><text x="73" y="197" font-family="Arial,sans-serif" font-size="10" fill="#d5e4ff">A space to grow</text>
 <g transform="translate(0 ${w})"><text x="49" y="258" font-family="Arial,sans-serif" font-size="39" font-weight="700" letter-spacing="-1" fill="white">Good things</text><text x="49" y="305" font-family="Arial,sans-serif" font-size="39" font-weight="700" letter-spacing="-1" fill="white">start together.</text>
 <text x="50" y="342" font-family="Arial,sans-serif" font-size="13" fill="#bdcfee">Learn, connect, and build your next chapter.</text>
 </g><rect x="49" y="394" width="346" height="99" rx="12" fill="#ffffff" opacity=".07"/><path d="m72 423 5 5 9-12" fill="none" stroke="#a7d8c2" stroke-width="2"/><text x="99" y="428" font-family="Arial,sans-serif" font-size="13" fill="#e7efff">Your people. Your possibilities.</text><text x="71" y="461" font-family="Arial,sans-serif" font-size="12" fill="#bdcfee">One account to bring it all together.</text><text x="50" y="563" font-family="Arial,sans-serif" font-size="10" fill="#a0b5d9">A little space for big ideas.</text>
 </g><g transform="translate(0 ${h})"><text x="570" y="144" font-family="Arial,sans-serif" font-size="27" font-weight="700" letter-spacing="-.7" fill="#18233b">Create your account</text><text x="571" y="170" font-family="Arial,sans-serif" font-size="12" fill="#8790a2">Make room for what comes next.</text></g>
 <rect x="570" y="224" width="${145-s}" height="40" rx="7" fill="#fff" stroke="#dce2eb"/><rect x="${725+s}" y="224" width="${145-s}" height="40" rx="7" fill="#fff" stroke="#dce2eb"/><text x="592" y="249" font-family="Arial,sans-serif" font-size="15" font-weight="700" fill="#4285f4">G</text><text x="617" y="248" font-family="Arial,sans-serif" font-size="11" fill="#384257">Google</text><path d="M750 239c-7-1-8 11-1 14 2 1 3-1 5-1 2 0 3 1 5 0 1-2 2-4 2-5-5-2-4-6 0-8-3-4-6-2-8-1-1-2-2-2-3-1m4-5c1-4 4-5 5-5 0 3-2 5-5 5" fill="#243047"/><text x="779" y="248" font-family="Arial,sans-serif" font-size="11" fill="#384257">Apple</text>
 <path d="M570 289h114m72 0h114" stroke="#e7eaf0"/><text x="720" y="293" text-anchor="middle" font-family="Arial,sans-serif" font-size="10" fill="#a0a7b3">or with email</text>
 <text x="571" y="321" font-family="Arial,sans-serif" font-size="11" fill="#536079">Email address</text><rect x="570" y="332" width="300" height="40" rx="7" fill="#fafbfe" stroke="#dce2eb"/><text x="584" y="356" font-family="Arial,sans-serif" font-size="11" fill="#a3adbc">you@example.com</text>
 <g transform="translate(0 ${f})"><text x="571" y="396" font-family="Arial,sans-serif" font-size="11" fill="#536079">Password</text><rect x="570" y="407" width="300" height="40" rx="7" fill="#fafbfe" stroke="#dce2eb"/><text x="584" y="431" font-family="Arial,sans-serif" font-size="15" letter-spacing="3" fill="#8994a9">••••••••</text><path d="M843 427q7-9 14 0-7 9-14 0zm7 0h.01" fill="none" stroke="#a0aabd" stroke-width="1.5"/></g>
 ${b?`<path d="M882 ${447+f}v${8+b}m-4-${8+b}h8m-8 ${8+b}h8" stroke="#2d9f76" fill="none" stroke-width="1.5"/><text x="895" y="${457+f+b/2}" font-family="Arial,sans-serif" font-size="9" fill="#298666">${8+b}px</text>`:''}<g transform="translate(0 ${b+f})"><rect x="570" y="455" width="300" height="43" rx="7" fill="#3069ed"/><text x="720" y="481" text-anchor="middle" font-family="Arial,sans-serif" font-size="12" font-weight="700" fill="#fff">Create account</text><text x="720" y="521" text-anchor="middle" font-family="Arial,sans-serif" font-size="9" fill="#939daf">By continuing, you agree to our Terms and Privacy Policy.</text></g><text x="720" y="575" text-anchor="middle" font-family="Arial,sans-serif" font-size="10" fill="#8490a4">Already have an account? <tspan fill="#3269d8">Sign in</tspan></text></g></svg>`;
}
function areaStyle(r){return `left:${r.x*100}%;top:${r.y*100}%;width:${r.w*100}%;height:${r.h*100}%`;}
function heading(){return `<div class="breadcrumbs"><a href="#issue">Product</a>${icon('chevron')}<a href="#issue">Issues</a>${icon('chevron')}<span>#107</span></div><div class="page-heading"><div><div class="issue-meta"><span class="type-tag">Design</span><span class="muted">Desktop</span><span class="tiny-dot"></span><span class="muted">Sample issue</span></div><h1>Desktop signup doesn’t fit the window</h1><p>Keep the fields and behaviour. Give the layout a little breathing room.</p></div><span class="status-pill"><i></i> Open</span></div>`;}
function screenshotBoard(id,uid,selectable=false){return `<div class="artboard ${selectable?'selectable':''}" ${selectable?'id="artboard"':''} data-image-version="${id}">${art(id,uid)}${selectable?pinsFor(state,id).map(t=>`<button class="pin ${selected===t.id?'active':''} ${t.phase==='resolved'?'resolved':''}" style="left:${(t.region.x+t.region.w/2)*100}%;top:${(t.region.y+t.region.h/2)*100}%" data-action="thread" data-id="${t.id}" aria-label="Feedback ${t.number}: ${esc(t.text)}">${t.phase==='resolved'?icon('check'):t.number}</button>`).join(''):''}${selectable&&draft?.versionId===id?`<div class="selection-box draft-box" style="${areaStyle(draft.region)}"><span>New feedback</span></div>`:selectable&&current()?.versionId===id?`<div class="selection-box saved-box" style="${areaStyle(current().region)}"></div>`:''}</div>`;}

function review(){const t=current(),latest=t?.revisionId,open=state.threads.filter(t=>t.phase!=='resolved').length;
return `${heading()}<section class="review-workspace" aria-label="Visual feedback workspace"><div class="viewer-toolbar"><div class="file-info"><span class="file-icon">${icon('image')}</span><div><strong>signup_default.png</strong><span>Illustrative attachment <b>·</b> 960 × 600</span></div></div><div class="toolbar-right"><span class="feature-label">${icon('pin')} Point and reply</span><button class="icon-button close-viewer" data-action="issue" aria-label="Close attachment and return to issue">${icon('close')}</button></div></div><div class="workspace-body"><section class="visual-pane" aria-label="Screenshot review"><div class="canvas-toolbar"><div class="segmented"><button data-action="original" class="${!compare&&versionId===(t?.versionId||draft?.versionId||'original')?'selected':''}">${(t?.versionId||draft?.versionId||'original')!=='original'?'Source':'Original'}</button><button data-action="revision" class="${!compare&&versionId===latest?'selected':''}" ${!latest?'disabled':''}>Revision ${!latest?'<span class="soon-dot"></span>':''}</button></div><div class="canvas-tools"><button class="icon-button ${compare?'is-active':''}" data-action="compare" aria-label="Compare source and revision side by side" title="Compare images" ${!latest?'disabled':''}>${icon('compare')}</button><span class="tool-divider"></span><button class="icon-button" data-action="zoom-out" aria-label="Zoom out" ${compare?'disabled':''}>${icon('minus')}</button><button class="zoom-label" data-action="fit" aria-label="Fit screenshot">${Math.round(zoom*100)}%</button><button class="icon-button" data-action="zoom-in" aria-label="Zoom in" ${compare?'disabled':''}>${icon('plus')}</button></div></div>
<div class="canvas ${compare?'comparing':''}" id="canvas">${compare&&latest?`<div class="comparison-grid"><div><p><span class="tiny-dot"></span> ${esc(version(t.versionId).label)} · feedback source</p>${screenshotBoard(t.versionId,'compare-source')}</div><div><p><span class="tiny-dot green"></span> ${esc(version(latest).label)} · sample adjustment</p>${screenshotBoard(latest,'compare-revision')}</div></div>`:`<div class="canvas-label"><span class="tiny-dot ${versionId==='original'?'':'green'}"></span>${esc(version().label)} ${versionId!=='original'?'<span>· sample spacing change</span>':''}</div><div class="artboard-wrap" id="artboard-wrap">${screenshotBoard(versionId,'primary',true)}</div>${!state.threads.length&&!draft?`<div class="canvas-hint">${icon('select')} Click an area, or drag to be more precise</div>`:''}`}</div>
<div class="canvas-bottom"><span>${icon('pin')} ${compare?'Compare the images against your feedback.':draft?'Area selected. Add your note in the feedback panel.':versionId!=='original'?'Sample spacing change. Compare it against your note.':'Feedback stays linked to this image version.'}</span><button class="text-button" data-action="choose-area">Choose an area ${icon('chevron')}</button></div></section><aside class="feedback-pane" aria-label="Feedback conversation"><div class="feedback-heading"><h2>Feedback <span class="count">${state.threads.length}</span></h2><button class="icon-button" data-action="new" aria-label="Add another feedback pin" title="New feedback">${icon('plus')}</button></div>${state.threads.length?`<div class="thread-list" aria-label="Feedback threads">${state.threads.map(x=>`<button data-action="thread" data-id="${x.id}" aria-label="Open feedback ${x.number}" aria-pressed="${selected===x.id&&!draft}" class="thread-chip ${selected===x.id&&!draft?'selected':''} ${x.phase==='resolved'?'done':''}">${x.phase==='resolved'?icon('check'):x.number}<span>${esc(x.targetLabel)}</span>${x.phase==='question'?'<i></i>':''}</button>`).join('')}</div>`:''}<div class="thread-content" id="thread-content">${draft?draftPanel():t?threadPanel(t):emptyPanel()}</div><div class="pane-foot"><span class="agent-mini">${icon('robot')}</span><span>Demo agent <span class="muted">· responses are scripted</span></span><i></i></div></aside></div></section><div class="under-workspace"><span>${icon('link')} One image. One clear conversation.</span><span>${open?`${open} open feedback ${open===1?'thread':'threads'}`:'No open feedback'} <span class="muted">· saved in this tab</span></span></div>`;}
function emptyPanel(){return `<div class="agent-intro"><span class="agent-avatar">${icon('robot')}</span><div><strong>Your agent</strong><span>Ready for your feedback</span></div></div><div class="welcome-note">“I’ve shared the layout. Point to anything you’d like me to adjust.”<span>Illustrative agent message</span></div><div class="empty-visual"><div class="empty-target"><span></span>${icon('pin')}</div><h3>Less explaining.<br>More pointing.</h3><p>Choose an area on the screenshot.<br>Your agent will see exactly where you mean.</p>${button(`${icon('pin')} Try the button area`,'suggest','primary full')}<span class="keyboard-note">You can also use “Choose an area” below the image.</span></div><div class="micro-steps"><span><b>1</b> Point</span><i></i><span><b>2</b> Explain</span><i></i><span><b>3</b> Review</span></div>`;}
function draftPanel(){return `<div class="section-kicker"><span class="draft-dot"></span> NEW FEEDBACK</div><h3 class="panel-title">What should change here?</h3><div class="area-card">${icon('select')}<div><strong>${esc(targetFor(draft.region).label)}</strong><span>${esc(version(draft.versionId).label)} · selected area</span></div><button class="icon-button" data-action="choose-area" aria-label="Change selected area">${icon('edit')}</button></div><label class="field-label" for="feedback-text">Your feedback</label><textarea id="feedback-text" maxlength="1500" rows="5" placeholder="Tell your agent what you’d like to change…">${esc(draft.text)}</textarea><div class="input-bottom"><span>Be specific. Your pin supplies the “where”.</span><span id="char-count">${draft.text.length}/1500</span></div>${button('Use example feedback','example','example-button')}<div class="recipient-line"><span class="agent-mini">${icon('robot')}</span> To your demo agent</div><div class="composer-actions">${button('Cancel','cancel-draft','subtle')}${button(`Send to agent ${icon('send')}`,'send','primary',draft.text.trim().length<3?'disabled':'')}</div><div class="soft-note">${icon('link')} The image, selected area, and your exact words travel together.</div>`;}
function message(m,t,index){return `<div class="message ${m.role}"><span class="message-avatar ${m.role==='agent'?'agent-avatar':'human-avatar'}">${m.role==='agent'?icon('robot'):'OA'}</span><div class="message-main"><div class="message-by"><strong>${m.role==='agent'?'Your agent':'You'}</strong><span>${index===0?'Feedback':m.revisionId?'Sample revision':''}</span></div><p>${esc(m.text)}</p>${m.revisionId?button(`${icon('compare')} View this revision`,'show-revision','inline-revision',`data-version="${m.revisionId}"`):''}</div></div>`;}
function crop(t){const r=t.region;return `<div class="context-crop">${art(t.versionId,'context-crop').replace('viewBox="0 0 960 600"',`viewBox="${r.x*960} ${r.y*600} ${r.w*960} ${r.h*600}"`)}</div>`;}
function threadPanel(t){const phase={sent:['Sent to agent','blue'],question:['Your input needed','amber'],working:['Preparing sample revision','blue'],ready:['Ready for your review','blue'],resolved:['Resolved','green']}[t.phase];
return `<div class="thread-top"><span class="phase ${phase[1]}"><i></i>${phase[0]}</span>${['sent','question'].includes(t.phase)&&!t.revisionId?`<details class="note-menu"><summary aria-label="Feedback actions">•••</summary><div>${button(`${icon('edit')} Edit feedback`,'edit-note')}${button(`${icon('trash')} Delete feedback`,'delete-note')}</div></details>`:''}</div><button class="source-link" data-action="source">${icon('pin')} Pin ${t.number} on ${esc(version(t.versionId).label)} ${icon('arrow')}</button>${editing===t.id?`<label class="field-label" for="edit-text">Edit your feedback</label><textarea id="edit-text" rows="4" maxlength="1500">${esc(t.text)}</textarea><div class="composer-actions">${button('Cancel','cancel-edit','subtle')}${button('Save feedback','save-edit','primary')}</div>`:`<div class="messages">${t.messages.map((m,i)=>message(m,t,i)).join('')}</div>`}
${t.phase==='sent'||t.phase==='working'?`<div class="typing-row"><span class="agent-mini">${icon('robot')}</span><span class="typing"><i></i><i></i><i></i></span><span>${t.phase==='sent'?'Reading the linked feedback…':'Rendering a sample spacing adjustment…'}</span></div>`:''}
${t.phase==='question'?`<div class="clarify-card"><span class="section-kicker">YOUR REPLY</span>${button('Only the selected area','answer-area','choice')}${button('The surrounding layout too','answer-layout','choice')}<label class="sr-only" for="custom-answer">Write a different answer</label><div class="answer-composer"><input id="custom-answer" maxlength="1500" placeholder="Or give your own direction…"><button class="icon-button" data-action="answer-custom" aria-label="Send your answer">${icon('send')}</button></div></div>`:''}
${['ready','resolved'].includes(t.phase)?`<div class="resolution-card ${t.phase==='resolved'?'is-resolved':''}">${t.phase==='resolved'?`<span class="resolved-icon">${icon('check')}</span><h3>A clear finish, together.</h3><p>This feedback is resolved. Your note, the reply, and the revision stay linked.</p>${button(`${icon('refresh')} Reopen feedback`,'reopen','subtle full')}`:`<h3>Does the revision address your note?</h3><p>Compare first. You decide whether it’s resolved.</p>${button(`${icon('compare')} Compare images`,'compare','secondary full')}${button(`${icon('check')} Resolve feedback`,'resolve','primary full')}${button('Needs another pass','reopen','text-button full')}`}</div>`:''}
${reopening?`<div class="reopen-composer"><label class="field-label" for="reopen-text">What still needs work?</label><textarea id="reopen-text" rows="3" maxlength="1500" placeholder="Tell your agent what to adjust next…"></textarea><div class="composer-actions">${button('Cancel','cancel-reopen','subtle')}${button('Send follow-up','send-reopen','primary')}</div></div>`:''}
<details class="shared-context"><summary>${icon('link')} What your agent receives ${icon('chevron')}</summary><div>${crop(t)}<dl><dt>Issue</dt><dd>#107 · Desktop signup</dd><dt>Image</dt><dd>${esc(version(t.versionId).label)} · signup_default.png</dd><dt>Area</dt><dd>${esc(t.targetLabel)} (${Math.round(t.region.w*100)}% × ${Math.round(t.region.h*100)}% of the image)</dd></dl><blockquote>${esc(t.text)}</blockquote>${t.scope?`<p><strong>Your direction:</strong> ${esc(t.scope)}</p>`:''}<p>The exact region and image version are included. This is a local preview of the shared context, not a live delivery receipt.</p>${button('Copy context','copy-context','subtle')}</div></details>`;}

function issuePage(){return `${heading()}<div class="issue-layout"><section class="issue-main"><div class="issue-section"><h2>Description</h2><p>The desktop signup form needs to fit the default window. Adjust layout and spacing while keeping the fields, validation, and signup behaviour unchanged.</p><p class="muted">This independent demo adapts issue #107. The attachment below is a newly illustrated sample, not the original screenshot.</p></div><div class="issue-section"><div class="section-title"><h2>Attachments <span class="count">1</span></h2><span class="muted">Give feedback where it matters</span></div><button class="attachment-card" data-action="review"><div class="attachment-thumb">${art('original','thumbnail')}<span>${icon('pin')} Open visual feedback ${icon('arrow')}</span></div><div class="attachment-caption"><span class="file-icon">${icon('image')}</span><div><strong>signup_default.png</strong><span>Illustrative attachment · 960 × 600</span></div>${icon('arrow')}</div></button></div><div class="issue-section"><div class="section-title"><h2>Conversation</h2><span class="count">${state.threads.length}</span></div>${state.threads.length?state.threads.map(t=>`<button class="issue-thread" data-action="open-thread" data-id="${t.id}"><span class="pin-static">${t.number}</span><div><strong>${esc(t.text)}</strong><span>Visual feedback · ${esc(version(t.versionId).label)} · ${t.phase==='resolved'?'Resolved':'Open'}</span></div>${icon('chevron')}</button>`).join(''):`<div class="conversation-empty">${icon('message')}<div><strong>Keep the conversation attached to the work.</strong><p>Open the screenshot and point to an area to start.</p></div></div>`}</div></section><aside class="issue-sidebar"><div><span class="section-kicker">STATUS</span><p><span class="status-pill"><i></i> Open</span></p></div><div><span class="section-kicker">YOUR AGENT</span><div class="agent-intro"><span class="agent-avatar">${icon('robot')}</span><div><strong>Demo agent</strong><span>Scripted responses</span></div></div></div><div><span class="section-kicker">SCOPE</span><p>Layout and spacing only.</p><p class="muted">No live Ziki data, agent, or code is changed.</p></div><a class="text-button" href="https://ziki.dev/issues/107" target="_blank" rel="noreferrer">View the source issue ${icon('arrow')}</a></aside></div>`;}
function render(preserveInput=false){const active=document.activeElement;const input=preserveInput&&active?.matches('input,textarea')?{id:active.id,value:active.value,start:active.selectionStart,end:active.selectionEnd}:null;const focus=$('#thread-content')?.scrollTop||0;$('#main').innerHTML=`<div class="page-shell">${page==='issue'?issuePage():review()}</div>`;bindCanvas();resizeArtboard();if($('#thread-content'))$('#thread-content').scrollTop=focus;if(input){const field=document.getElementById(input.id);if(field){field.value=input.value;field.focus({preventScroll:true});field.setSelectionRange(input.start,input.end);}}}
function resizeArtboard(){const board=$('#artboard'),canvas=$('#canvas');if(board&&canvas)board.style.width=`${Math.max(240,Math.min(960,canvas.clientWidth-48,window.innerWidth>820?Math.max(300,(canvas.clientHeight-110)*1.6):960))*zoom}px`;}
function theme(){const light=document.documentElement.dataset.theme==='light';$('#theme').innerHTML=icon(light?'moon':'sun');$('#theme').setAttribute('aria-label',`Switch to ${light?'dark':'light'} mode`);}
try{document.documentElement.dataset.theme=localStorage.getItem('ziki-feedback-theme')||'dark';}catch{}theme();$('#theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='light'?'dark':'light';try{localStorage.setItem('ziki-feedback-theme',document.documentElement.dataset.theme);}catch{}theme();};
function regionFor(target){const c=version().changes,r={...target};if(target.id==='heading')r.y+=Math.min(3,c.heading||0)*7/600;if(target.id==='fields')r.h+=Math.min(2,c.fields||0)*5/600;if(target.id==='welcome')r.y+=Math.min(3,c.welcome||0)*7/600;if(target.id==='button')r.y+=(Math.min(2,c.button||0)*14+Math.min(2,c.fields||0)*5)/600;return r;}
function startDraft(region,text=''){draft={region:normalizeRegion(region),versionId,text:text||draft?.text||''};selected=null;compare=false;editing=null;reopening=false;render();$('#feedback-text')?.focus({preventScroll:true});announce('Area selected. Write your feedback.');if(window.innerWidth<=820)scrollToElement('.feedback-pane');}
function bindCanvas(){const board=$('#artboard');if(!board)return;let start=null,box=null;
 board.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.button!==0)return;const rect=board.getBoundingClientRect();start={x:Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),y:Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height)),px:e.clientX,py:e.clientY};board.setPointerCapture(e.pointerId);box=document.createElement('div');box.className='selection-box live-box';board.append(box);});
 board.addEventListener('pointermove',e=>{if(!start)return;const rect=board.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),y=Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height));box.style.cssText=areaStyle({x:Math.min(start.x,x),y:Math.min(start.y,y),w:Math.abs(x-start.x),h:Math.abs(y-start.y)});});
 board.addEventListener('pointerup',e=>{if(!start)return;const rect=board.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),y=Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height)),small=Math.hypot(e.clientX-start.px,e.clientY-start.py)<8;const r=small?{x:x-.045,y:y-.04,w:.09,h:.08}:{x:Math.min(start.x,x),y:Math.min(start.y,y),w:Math.abs(x-start.x),h:Math.abs(y-start.y)};start=null;box?.remove();startDraft(r);});
 board.addEventListener('pointercancel',()=>{start=null;box?.remove();});
}
function scrollToElement(selector){document.querySelector(selector)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
function dialog(content){$('#dialog-content').innerHTML=`<button class="icon-button dialog-close" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button>${content}`;$('#info-dialog').showModal();}
function selectThread(id){selected=id;draft=null;editing=null;reopening=false;compare=false;versionId=current()?.revisionId||current()?.versionId||'original';render();}
function route(next){page=next;location.hash=next==='issue'?'issue':'review';render();window.scrollTo({top:0,behavior:'smooth'});}
document.addEventListener('input',e=>{if(e.target.id==='feedback-text'&&draft){draft.text=e.target.value;$('#char-count').textContent=`${draft.text.length}/1500`;document.querySelector('[data-action="send"]').disabled=draft.text.trim().length<3;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&draft&&!$('#info-dialog').open){draft=null;render();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&e.target.id==='feedback-text'){e.preventDefault();document.querySelector('[data-action="send"]')?.click();}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,t=current();
 if(a==='close-dialog'){$('#info-dialog').close();return;}
 if(a==='issue'||a==='review'){route(a);return;}
 if(a==='new'){draft=null;selected=null;compare=false;render();toast('Click or drag on the screenshot, or choose an area below it.');return;}
 if(a==='suggest'){versionId='original';startDraft(TARGETS[3]);return;}
 if(a==='choose-area'){dialog(`<span class="section-kicker">KEYBOARD-FRIENDLY SELECTION</span><h2>Where should your agent look?</h2><p>Choose a named area. You can also click or drag on the image.</p><div class="area-options">${TARGETS.map(x=>button(`${icon('select')} ${x.label}`,'pick-area','choice',`data-target="${x.id}"`)).join('')}</div>`);return;}
 if(a==='pick-area'){$('#info-dialog').close();compare=false;startDraft(regionFor(TARGETS.find(x=>x.id===el.dataset.target))); return;}
 if(a==='example'){draft.text=targetFor(draft.region).id==='button'?'Please add more space above the Create account button. Keep the fields and signup behaviour unchanged.':`Please give the ${targetFor(draft.region).label.toLowerCase()} more breathing room. Keep the fields and behaviour unchanged.`;render();$('#feedback-text').focus({preventScroll:true});return;}
 if(a==='cancel-draft'){draft=null;render();return;}
 if(a==='send'){if(!draft)return;const d={...draft};if(dispatch({type:'create',...d})){selected=state.threads.at(-1).id;draft=null;render();announce('Feedback sent with the selected screenshot area.');}else toast('Write at least three characters. This demo supports up to 30 feedback threads.');return;}
 if(a==='thread'){selectThread(el.dataset.id);return;}
 if(a==='open-thread'){selectThread(el.dataset.id);route('review');return;}
 if(a==='original'||a==='source'){versionId=t?.versionId||draft?.versionId||'original';compare=false;render();return;}
 if(a==='revision'){if(t?.revisionId){versionId=t.revisionId;compare=false;render();}return;}
 if(a==='compare'){if(t?.revisionId){compare=!compare;render();if(window.innerWidth<=820)scrollToElement('.visual-pane');announce(compare?'Showing source and sample revision side by side.':'Showing one image.');}return;}
 if(a==='show-revision'){versionId=el.dataset.version;compare=false;render();return;}
 if(a==='zoom-in'||a==='zoom-out'||a==='fit'){zoom=a==='fit'?1:Math.max(.75,Math.min(1.5,zoom+(a==='zoom-in'?.25:-.25)));render();return;}
 if(a.startsWith('answer-')){const text=a==='answer-area'?'Adjust only the selected area. Keep everything else unchanged.':a==='answer-layout'?'You may adjust the surrounding layout too. Preserve fields and behaviour.':$('#custom-answer').value;if(dispatch({type:'answer',id:t.id,text,mode:a==='answer-area'?'area':a==='answer-layout'?'layout':'custom'})){render();announce('Your direction was sent. Preparing an illustrative revision.');}else toast('Write a little more detail before sending.');return;}
 if(a==='resolve'){dispatch({type:'resolve',id:t.id});render();toast('Feedback resolved. The linked conversation is kept.');return;}
 if(a==='reopen'){reopening=true;render();$('#reopen-text').focus({preventScroll:true});if(window.innerWidth<=820)scrollToElement('.reopen-composer');return;}
 if(a==='cancel-reopen'){reopening=false;render();return;}
 if(a==='send-reopen'){if(dispatch({type:'reopen',id:t.id,text:$('#reopen-text').value})){reopening=false;compare=false;render();announce('Feedback reopened and follow-up sent.');}else toast('Tell your agent what still needs work.');return;}
 if(a==='edit-note'){editing=t.id;render();$('#edit-text').focus({preventScroll:true});return;}
 if(a==='cancel-edit'){editing=null;render();return;}
 if(a==='save-edit'){if(dispatch({type:'edit',id:t.id,text:$('#edit-text').value})){editing=null;render();}else toast('Write at least three characters.');return;}
 if(a==='delete-note'){undoState=structuredClone(state);dispatch({type:'delete',id:t.id});selected=state.threads.at(-1)?.id||null;render();toast('Feedback removed.');dialog(`<h2>Feedback removed</h2><p>You can restore this feedback and its conversation.</p>${button('Undo removal','undo','primary')}${button('Keep removed','close-dialog','subtle')}`);return;}
 if(a==='undo'){if(undoState){state=undoState;undoState=null;save();selected=state.threads.at(-1)?.id;render();schedule();toast('Feedback restored.');}$('#info-dialog').close();return;}
 if(a==='copy-context'){try{await navigator.clipboard.writeText(JSON.stringify(agentInput(state,t.id),null,2));toast('The shared feedback context was copied.');}catch{toast('Clipboard unavailable. The context is shown above.');}return;}
 if(a==='about'){dialog(`<span class="section-kicker">POINT AND REPLY</span><h2>Give feedback where it belongs.</h2><p>On the inspected Ziki issue, screenshots open separately from the conversation. People have to describe the part they mean.</p><div class="about-flow"><strong>Point to an area</strong><span>→</span><strong>Discuss it with your agent</strong><span>→</span><strong>Compare the revision</strong></div><p>This proposal links an image version, selected region, feedback, and replies. Existing issue navigation stays intact.</p><p class="muted">This is a functional local interaction with a scripted agent and illustrated sample images. It does not generate arbitrary revisions, deliver messages to Ziki, or approve code. Different selected areas produce preset spacing variations.</p><a class="text-button" href="https://ziki.dev/issues/107" target="_blank" rel="noreferrer">View the original Ziki issue ${icon('arrow')}</a>`);return;}
 if(a==='reset'){dialog(`<h2>Start a fresh conversation?</h2><p>This clears the feedback and sample revisions saved in this browser tab. It does not change anything on Ziki.</p>${button('Cancel','close-dialog','subtle')}${button('Reset demo','confirm-reset','primary')}`);return;}
 if(a==='confirm-reset'){for(const timer of timers.values())clearTimeout(timer);timers.clear();dispatch({type:'reset'});selected=null;draft=null;versionId='original';compare=false;reopening=false;editing=null;$('#info-dialog').close();render();toast('Fresh image. Ready for your feedback.');}
});
window.addEventListener('hashchange',()=>{page=location.hash==='#issue'?'issue':'review';render();});
window.addEventListener('resize',resizeArtboard);
render();schedule();
